    private static readonly FrozenDictionary<string, MobSpawnDefinition[]> ByMap = All
        .GroupBy(spawn => spawn.Map, StringComparer.OrdinalIgnoreCase)
        .ToFrozenDictionary(group => group.Key, group => group.ToArray(), StringComparer.OrdinalIgnoreCase);

    internal static int Count => All.Length;
    internal static bool TryGetMap(string map, out IReadOnlyList<MobSpawnDefinition> spawns)
    {
        if (ByMap.TryGetValue(map, out var found)) { spawns = found; return true; }
        spawns = []; return false;
    }
    internal static IReadOnlyList<MobSpawnDefinition> GetForMap(string map) => ByMap.TryGetValue(map, out var found) ? found : [];
